import { test, expect } from '@playwright/test';

test.describe('Async Image Upload Progress', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/upload');
  });

  test('should display progress percentage during async image upload', async ({ page }) => {
    // Setup: intercept the upload API endpoint
    await page.route('**/api/upload', (route) => {
      route.abort('blockedbyclient');
    });

    // Get the file input using getByLabel
    const fileInput = page.getByLabel('Upload Image');
    await fileInput.setInputFiles('playwright/fixtures/sample-image.jpg');

    // Get the upload button using getByRole
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await uploadButton.click();

    // Wait for the upload progress to appear
    const progressBar = page.getByTestId('upload-progress-bar');
    await expect(progressBar).toBeVisible();

    // Verify initial progress state
    const progressText = page.getByTestId('progress-percentage');
    await expect(progressText).toContainText('0%');

    // Wait for progress to update
    await page.waitForTimeout(500);

    // Verify progress has increased
    await expect(progressText).toContainText('25%');

    // Wait for more progress
    await page.waitForTimeout(500);

    // Verify progress has increased again
    await expect(progressText).toContainText('75%');

    // Wait for upload to complete
    await page.waitForTimeout(500);

    // Verify progress is 100%
    await expect(progressText).toContainText('100%');

    // Verify success message appears
    const successMessage = page.getByTestId('upload-success-message');
    await expect(successMessage).toBeVisible();
    await expect(successMessage).toContainText('Upload complete');

    // Verify progress bar is filled
    await expect(progressBar).toHaveClass(/progress-bar--filled/);
  });

  test('should handle upload failure and display error message', async ({ page }) => {
    // Setup: intercept the upload API endpoint and simulate failure
    await page.route('**/api/upload', (route) => {
      route.abort('blockedbyclient');
    });

    // Get the file input using getByLabel
    const fileInput = page.getByLabel('Upload Image');
    await fileInput.setInputFiles('playwright/fixtures/sample-image.jpg');

    // Get the upload button using getByRole
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await uploadButton.click();

    // Wait for progress to appear
    const progressBar = page.getByTestId('upload-progress-bar');
    await expect(progressBar).toBeVisible();

    // Wait for progress to update
    await page.waitForTimeout(500);

    // Verify progress is visible
    const progressText = page.getByTestId('progress-percentage');
    await expect(progressText).toContainText('25%');

    // Wait for upload to fail
    await page.waitForTimeout(500);

    // Verify error message appears
    const errorMessage = page.getByTestId('upload-error-message');
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText('Upload failed');

    // Verify progress bar is not filled
    await expect(progressBar).not.toHaveClass(/progress-bar--filled/);

    // Verify retry button is visible
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();

    // Verify upload button is enabled for retry
    await expect(uploadButton).toBeEnabled();
  });
});
